import unittest


def pluck(arr):
    if(len(arr) == 0): return []
    evens = list(filter(lambda x: x%2 == 0, arr))
    if(evens == []): return []
    return [min(evens), arr.index(min(evens))]


# Unit test for function pluck
class TestPluck(unittest.TestCase):

    def test_empty_array(self):
        self.assertEqual(pluck([]), [])

    def test_no_even_values(self):
        self.assertEqual(pluck([1, 3, 5, 7]), [])

    def test_single_even_element(self):
        self.assertEqual(pluck([4]), [4, 0])

    def test_single_odd_element(self):
        self.assertEqual(pluck([3]), [])

    def test_basic_case(self):
        self.assertEqual(pluck([4, 2, 3]), [2, 1])

    def test_smallest_even_at_end(self):
        self.assertEqual(pluck([1, 2, 3]), [2, 1])

    def test_multiple_evens_picks_smallest(self):
        self.assertEqual(pluck([5, 0, 3, 0, 4, 2]), [0, 1])

    def test_duplicate_smallest_returns_first_index(self):
        self.assertEqual(pluck([2, 4, 2, 6]), [2, 0])

    def test_negative_evens(self):
        self.assertEqual(pluck([-4, -2, 3]), [-4, 0])

    def test_all_even_values(self):
        self.assertEqual(pluck([8, 6, 4, 2]), [2, 3])

    def test_zero_is_even(self):
        self.assertEqual(pluck([1, 0, 5]), [0, 1])

    def test_large_values(self):
        self.assertEqual(pluck([1000000, 999998, 3]), [999998, 1])

    def test_even_and_odd_mixed(self):
        self.assertEqual(pluck([7, 1, 5, 3, 8, 9]), [8, 4])

    def test_result_format(self):
        result = pluck([2, 3, 4])
        self.assertIsInstance(result, list)
        self.assertEqual(len(result), 2)


if __name__ == "__main__":
    unittest.main()
